} return true;
};

function settype(Type) {
	if (!String(source.getVariable())) {
    source.setVariable(JSON.stringify(r, null, "\t"));
    }
    var lists =
		JSON.parse(source.getVariable());
		    lists.type = Type;
    if (Type == '小说') {
        lists.module = "fictions";
    }else if (Type == '视频') {
        lists.module = "videos";
    };
    source.setVariable(JSON.stringify(lists, null, "\t"));
    java.toast('已将类型切换为:' + Type);
}
