function wz() {
    try {
        let ua = java.getWebViewUA();
        let html = java.get(getUrl(), { 'user-agent': ua });
        code = html.statusCode();
        //java.log(code);
        return getUrl();
    } catch (error) {
        let urls = [];
        let url = "https://xiaohuangshu.me/";
        let ua = java.getWebViewUA();
        let result = java.get(url, { 'user-agent': ua }).body();
        let uri = result.match(/<a href="(.*?)" target="/g);
        //java.log(uri.join('\n'))
        if (uri) {
            let urlso = uri.map(match => match.replace(/<a href="(.*?)" target="/g, "$1"));
            urlso = Array.from(new Set(urlso));
            urls = urls.push(urlso);
        }
        return urls[1];
    }
}

